@file:Suppress("UnstableApiUsage")

package ckbuild.providertests

import com.android.build.api.dsl.*
import org.gradle.api.*
import org.gradle.api.tasks.testing.*
import org.gradle.kotlin.dsl.*
import org.jetbrains.kotlin.gradle.dsl.*
import org.jetbrains.kotlin.gradle.plugin.*

class TestFilters(
    val androidTestRegex: String,
    val kotlinTestFilter: TestFilter.() -> Unit,
)

// `restore` tests validate all data in the test storage, which could be generated by other providers and platforms
fun Project.applyProviderTestFilters() {
    val testFilters = providers.gradleProperty("ckbuild.providerTests.step").orElse("generate").map { providerTestsStep ->
        when (providerTestsStep) {
            // generate and validate data, without validation of the whole test storage
            "generate" -> TestFilters(
                androidTestRegex = "^((?!AlgorithmTest#restore$).)*$",
                kotlinTestFilter = {
                    setExcludePatterns("*AlgorithmTest.restore")
                }
            )
            // validate data in the test storage, f.e. merged from other platforms
            "restore" -> TestFilters(
                androidTestRegex = "^.*AlgorithmTest#restore$",
                kotlinTestFilter = {
                    setIncludePatterns("*AlgorithmTest.restore")
                }
            )
            else -> error("wrong argument")
        }
    }

    plugins.withId("org.jetbrains.kotlin.multiplatform") {
        extensions.configure<KotlinMultiplatformExtension>("kotlin") {
            targets.withType<KotlinTargetWithTests<*, *>>().configureEach {
                testRuns.configureEach {
                    filter(testFilters.get().kotlinTestFilter)
                }
            }

            plugins.withId("com.android.kotlin.multiplatform.library") {
                extensions.configure<KotlinMultiplatformAndroidLibraryTarget> {
                    compilations.withType(KotlinMultiplatformAndroidDeviceTestCompilation::class).configureEach {
                        instrumentationRunnerArguments["tests_regex"] = testFilters.get().androidTestRegex
                    }
                }
            }
        }
    }
}
